css:
@import url("https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700&family=Montserrat:wght@400;500;600&display=swap");
:root{--oc:#12355B;--oc2:#0C2640;--sg:#D9B26F;--ps:#F3EDE2;--ink:#1B2533;--gr:#5A6472;--ln:#E4DCCD;--h:"Cinzel",Georgia,serif;--b:"Montserrat",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:16px;line-height:1.7;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:500;margin:0;line-height:1.15}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--sg);padding:8px;z-index:99}
:focus-visible{outline:2px solid var(--sg);outline-offset:3px}
.hero{position:relative;min-height:700px;color:#fff;display:flex;flex-direction:column;background:var(--oc2)}
.hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(12,38,64,.6),rgba(12,38,64,.3) 35%,rgba(12,38,64,.85))}
.nav{position:relative;z-index:5;display:flex;justify-content:space-between;align-items:center;height:90px}.logo{font-family:var(--h);font-size:24px;font-weight:700;text-decoration:none;letter-spacing:.08em}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0;font-size:15px;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:var(--sg)}
.burger{display:none;background:none;border:1px solid #fff;color:#fff;width:44px;height:40px;font-size:20px;cursor:pointer}
.hc{position:relative;z-index:3;margin-top:auto;text-align:center;padding-bottom:30px}.hero h1{font-size:clamp(40px,6vw,82px);letter-spacing:.02em}.hero p{font-size:18px;max-width:34em;margin:14px auto 30px;color:#fff;text-shadow:0 1px 8px rgba(0,0,0,.5)}
.bk{position:relative;z-index:4;background:#fff;color:var(--ink);display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:0;max-width:960px;margin:0 auto -50px;box-shadow:0 20px 50px rgba(12,38,64,.25);text-align:left}
.bk>div{padding:16px 20px;border-right:1px solid var(--ln);min-width:0}.bk label{display:block;font-size:12px;font-weight:600;letter-spacing:.08em;color:var(--gr);margin-bottom:4px}.bk input,.bk select{width:100%;font:500 16px var(--b);border:0;padding:4px 0;color:var(--ink);background:#fff}
.bk button{font:600 15px var(--b);background:var(--oc);color:#fff;border:0;padding:0 30px;cursor:pointer;letter-spacing:.06em}
.btn{display:inline-block;background:var(--oc);color:#fff;text-decoration:none;font:600 15px var(--b);padding:14px 26px;border:0;cursor:pointer;letter-spacing:.06em}.btn.g{background:var(--sg);color:var(--ink)}
section{padding:90px 0}.sh{text-align:center;max-width:640px;margin:0 auto 40px}.sh h2{font-size:clamp(32px,4vw,50px);color:var(--oc)}.sh p{color:var(--gr);margin:12px 0 0}
.intro{padding-top:130px}.intro .wrap{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.intro h2{font-size:clamp(30px,3.6vw,44px);color:var(--oc)}.intro p{color:var(--gr)}
.intro .im{display:grid;grid-template-columns:1fr 1fr;gap:14px}.intro .im img{width:100%;aspect-ratio:3/4;object-fit:cover}.intro .im img:last-child{margin-top:40px}
.rooms{background:var(--ps)}.stay{text-align:center;color:var(--gr);margin:-20px 0 30px;font-weight:500}
.rm{display:grid;grid-template-columns:1fr 1.2fr auto;gap:30px;align-items:center;background:#fff;margin-bottom:18px}
.rm img{width:100%;height:100%;min-height:220px;object-fit:cover}.rm .c{padding:24px 0}.rm h3{font-size:26px;color:var(--oc)}.rm p{color:var(--gr);margin:8px 0 12px}
.rm ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:6px 16px;font-size:14px;color:var(--gr)}.rm ul li:before{content:"· ";color:var(--sg);font-weight:700}
.rm .pr{padding:24px 28px;text-align:right;border-left:1px solid var(--ln);min-width:220px}.rm .pr b{display:block;font-family:var(--h);font-size:30px;color:var(--oc)}.rm .pr small{display:block;color:var(--gr);font-size:13px}.rm .pr .tot{font-weight:600;margin:10px 0 14px;font-size:15px}
.rm .pr button{font:600 14px var(--b);background:var(--oc);color:#fff;border:0;padding:11px 18px;cursor:pointer;letter-spacing:.05em}.rm .pr button[aria-pressed=true]{background:var(--sg);color:var(--ink)}
.rm.full .pr button{background:#C9CED6;cursor:not-allowed}
.sum{background:var(--oc);color:#fff;padding:24px 28px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-top:24px}.sum b{font-family:var(--h);font-size:28px;color:var(--sg);font-weight:500}
.am{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:30px}.am div{text-align:center}.am svg{margin:0 auto 12px}.am h3{font-size:19px;color:var(--oc)}.am p{color:var(--gr);font-size:15px;margin:6px 0 0}
.gal{display:grid;grid-template-columns:2fr 1fr 1fr;gap:0}.gal img{width:100%;height:100%;aspect-ratio:1/1;object-fit:cover}.gal img:first-child{aspect-ratio:2/1}
.msg{visibility:hidden;font-weight:600;margin:10px 0 0}.msg.on{visibility:visible}
footer{background:var(--oc2);color:#AFBCCC;padding:34px 0;font-size:14px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.bk{grid-template-columns:1fr 1fr;margin:0 24px -50px}.bk button{grid-column:1/-1;padding:14px}.intro .wrap{grid-template-columns:1fr}.rm{grid-template-columns:1fr}.rm .c{padding:0 24px}.rm .pr{border-left:0;border-top:1px solid var(--ln);text-align:left}.am{grid-template-columns:1fr 1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:90px;left:0;right:0;background:var(--oc2);flex-direction:column;padding:18px 24px;z-index:30}.menu.open{display:flex}.bk{grid-template-columns:1fr}.bk>div{border-right:0;border-bottom:1px solid var(--ln)}.intro{padding-top:200px}.gal{grid-template-columns:1fr 1fr}.gal img:first-child{grid-column:1/-1}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=700&q=75&auto=format&fit=crop`;const f=n=>'$'+Math.round(n).toLocaleString('en-US');
const R=[["Garden room","Ground floor room with a private terrace facing the tropical garden.",2,189,["King or twin beds","32 m²","Garden terrace"],"1582719478250-c89cae4dc85b","Bright bedroom with a large bed"],["Ocean view room","Upstairs room with a balcony and hammock looking out to sea.",2,249,["King bed","36 m²","Balcony with hammock"],"1566073771259-6a8506099945","Lodge with loungers by a pool"],["Family casita","Two bedrooms and a small kitchen, a short walk from the family pool.",4,329,["King plus two singles","58 m²","Kitchenette"],"1571896349842-33c89424de2d","Villas around a lit pool at dusk"],["Pool suite","Our best room, with its own plunge pool and an outdoor shower.",2,419,["King bed","64 m²","Private plunge pool"],"1551882547-ff40c63fe5fa","Palm trees reflected in a pool"]];
let pick=-1;const d0=new Date(Date.now()+30*864e5),d1=new Date(Date.now()+35*864e5);$('ci').value=d0.toISOString().slice(0,10);$('co').value=d1.toISOString().slice(0,10);$('ci').min=new Date().toISOString().slice(0,10);
function nights(){const n=Math.round((new Date($('co').value)-new Date($('ci').value))/864e5);return n>0?n:0}
function draw(){const n=nights(),g=+$('gu').value;$('stay').textContent=n?`${n} night${n>1?'s':''}, ${$('gu').selectedOptions[0].text}. Prices include taxes.`:'Check-out must be after check-in.';
$('rl').innerHTML=R.map((r,i)=>{const full=r[2]<g;return`<article class="rm${full?' full':''}"><img src="${U(r[5])}" alt="${r[6]}" width="700" height="440" loading="lazy"><div class="c"><h3>${r[0]}</h3><p>${r[1]}</p><ul>${r[4].map(x=>`<li>${x}</li>`).join('')}<li>Sleeps ${r[2]}</li></ul></div><div class="pr"><b>${f(r[3])}</b><small>per night</small><div class="tot">${n?f(r[3]*n)+' for '+n+' night'+(n>1?'s':''):'Choose dates'}</div><button type="button" data-i="${i}" aria-pressed="${i===pick}" ${full?'disabled':''}>${full?'Too small for your group':i===pick?'Selected ✓':'Select room'}</button></div></article>`}).join('');
if(pick>-1&&R[pick][2]<g)pick=-1;const r=R[pick];$('ss').textContent=r&&n?`${r[0]}, ${n} night${n>1?'s':''}`:'Choose a room to see your total.';$('st').textContent=r&&n?f(r[3]*n):''}
$('rl').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;pick=+b.dataset.i;draw()};
$('bkf').addEventListener('change',()=>{if(new Date($('co').value)<=new Date($('ci').value)){const d=new Date($('ci').value);d.setDate(d.getDate()+1);$('co').value=d.toISOString().slice(0,10)}draw()});
$('bkf').onsubmit=e=>{e.preventDefault();draw();$('rooms').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
$('bb').onclick=()=>{const m=$('msg');m.textContent=pick>-1?`Thank you. Your ${R[pick][0].toLowerCase()} from ${$('ci').value} to ${$('co').value} is on hold. We'll email you to confirm within a few hours.`:'Please select a room first.';m.classList.add('on')};draw();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
